/**
 * Self-hosted 402 settlement backend.
 *
 * The metered path (see `packages/gateway/src/broker.ts`) is:
 *
 *   rail.quote -> rail.authorize -> rail.settle -> origin.fetch(...)
 *
 * The rail's `settle` step is the payment commit. Previously `SelfHosted402Rail`
 * only extended the in-memory stub, so a "self 402" never actually minted a
 * proof, rejected a reused proof, or recorded a final receipt. This module
 * makes it real:
 *
 *   1. The broker signs an Ed25519 **payment mandate** (a spend authorization)
 *      over an opaque manifest, carrying a per-request nonce.
 *   2. The rail POSTs that signed mandate to a settlement backend. The backend
 *      verifies the signature, rejects a **replayed** nonce, signs a chained
 *      settlement **receipt**, and returns it. A replayed proof throws
 *      `RAIL_REPLAY` (non-retryable) — the broker maps a settle fault to
 *      `payment-required`, exactly as an origin that still demanded payment.
 *   3. The receipt lands in a small, Ed25519-**chained, tamper-evident ledger**
 *      that the audit/`reconcile` surface can read.
 *
 * The wire form is intentionally minimal (draft-caveat: build against the
 * *pattern* of x402's `PAYMENT-SIGNATURE`/`X-PAYMENT`, not its field names).
 * The same backend runs in-process (tests, dev) or behind a thin HTTP service
 * (`SettlementHttpServer`) on a separate host (`HttpSettlementClient`), so the
 * rail needs no compile-time knowledge of where the backend lives.
 *
 * Crypto mirrors `packages/identity/src/ring.ts`: Ed25519 over a JWK, and the
 * broker's own `b64url`/`fromB64url` from `@mwb/core`. No new dependency.
 */

import {
  generateKeyPairSync,
  sign,
  verify,
  createPrivateKey,
  createPublicKey,
  randomBytes,
} from 'node:crypto';
import {
  RailError,
  makeSettlementRef,
  systemClock,
  b64url,
  fromB64url,
  type Clock,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type Micros,
} from '@mwb/core';

/** The opaque mandate type the broker mints. Not a draft's field set. */
const PAYMENT_MANDATE_TYPE = 'urn:mwb:self402:payment-mandate:v1';

/** Fixed key order so the manifest bytes are byte-identical at sign and verify. */
const MANDATE_FIELDS = [
  'origin',
  'url',
  'amountMicros',
  'currency',
  'nonce',
  'issuedAt',
  'recipient',
] as const;

/** Accept a mandate whose `issuedAt` is within this window of the clock. */
const ACCEPTANCE_WINDOW_MS = 5 * 60 * 1000;

/** The header the rail injects on the settled origin request (holds the proof). */
export const PAYMENT_HEADER = 'x-payment';

/** An Ed25519 spend-authorizer. `privateKey` never leaves the signing side. */
export interface SettlementKey {
  keyId: string;
  algorithm: 'ed25519';
  /** 32-byte public key, JWK `x`, base64url. Shares the verifier. */
  publicKey: string;
  /** 32-byte seed, JWK `d`, base64url. Never leaves the broker. */
  privateKey: string;
  createdAt: string;
}

/** Mint a settlement key (broker's spend authorizer). */
export function makeSettlementKey(
  clock: Clock = systemClock,
  keyId = `settle_${clock.now().replace(/[^A-Za-z0-9]/g, '')}`,
): SettlementKey {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  const pub = publicKey.export({ format: 'jwk' }) as { x?: string };
  const priv = privateKey.export({ format: 'jwk' }) as { d?: string };
  if (!pub.x || !priv.d) {
    throw new RailError('failed to export Ed25519 JWK', 'SETTLEMENT_KEY');
  }
  return {
    keyId,
    algorithm: 'ed25519',
    publicKey: b64url(fromB64url(pub.x)),
    privateKey: b64url(fromB64url(priv.d)),
    createdAt: clock.now(),
  };
}

function privateKeyObject(k: SettlementKey): ReturnType<typeof createPrivateKey> {
  return createPrivateKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', d: k.privateKey, x: k.publicKey },
  });
}

function publicKeyObject(k: SettlementKey): ReturnType<typeof createPublicKey> {
  return createPublicKey({
    format: 'jwk',
    key: { kty: 'OKP', crv: 'Ed25519', x: k.publicKey },
  });
}

function signBytes(k: SettlementKey, buf: Buffer): string {
  return b64url(new Uint8Array(sign(null, buf, privateKeyObject(k))));
}

function verifyBytes(k: SettlementKey, buf: Buffer, sigB64: string): boolean {
  try {
    return verify(null, buf, publicKeyObject(k), Buffer.from(fromB64url(sigB64)));
  } catch {
    return false;
  }
}

/** The signed spend authorization the broker mints and the rail commits. */
export interface PaymentMandateManifest {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  recipient: string;
}

export interface PaymentMandate extends PaymentMandateManifest {
  signature: string;
}

function manifestBytes(m: PaymentMandateManifest): Buffer {
  const obj: Record<string, number | string> = {};
  for (const f of MANDATE_FIELDS) obj[f] = m[f];
  return Buffer.from(JSON.stringify(obj), 'utf8');
}

/** Build (sign) a payment mandate. */
export function buildMandate(o: {
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  recipient: string;
  clock: Clock;
  key: SettlementKey;
  nonce?: string;
  issuedAt?: string;
}): PaymentMandate {
  const nonce = o.nonce ?? randomBytes(32).toString('base64url');
  const issuedAt = o.issuedAt ?? o.clock.now();
  const manifest: PaymentMandateManifest = {
    origin: o.origin,
    url: o.url,
    amountMicros: o.amountMicros,
    currency: o.currency,
    nonce,
    issuedAt,
    recipient: o.recipient,
  };
  return { ...manifest, signature: signBytes(o.key, manifestBytes(manifest)) };
}

export interface VerifyResult {
  valid: boolean;
  reason?: string;
}

/**
 * Verify a mandate's signature, manifest, and acceptance window. Does not
 * consume the nonce — the origin can call this to gate content release.
 */
export function verifyMandate(
  m: PaymentMandate,
  key: SettlementKey,
  opts?: { nowMs?: number },
): VerifyResult {
  if (typeof m.signature !== 'string' || m.signature.length === 0) {
    return { valid: false, reason: 'missing-signature' };
  }
  if (!verifyBytes(key, manifestBytes(m), m.signature)) {
    return { valid: false, reason: 'signature-mismatch' };
  }
  const iat = Date.parse(m.issuedAt);
  if (Number.isNaN(iat)) return { valid: false, reason: 'bad-issuedAt' };
  const nowMs = opts?.nowMs ?? Date.now();
  if (Math.abs(nowMs - iat) > ACCEPTANCE_WINDOW_MS) {
    return { valid: false, reason: 'issued-out-of-window' };
  }
  if (!(m.amountMicros > 0)) return { valid: false, reason: 'non-positive-amount' };
  return { valid: true };
}

/** A receipt minted by the backend, signed by its key. */
export interface SettlementReceipt {
  settlementRef: string;
  origin: string;
  url: string;
  amountMicros: number;
  currency: string;
  nonce: string;
  issuedAt: string;
  settledAt: string;
}

/** One entry in the chained, tamper-evident settlement ledger. */
export interface LedgerRecord {
  seq: number;
  receipt: SettlementReceipt;
  signedAt: string;
  /** Signature over `${seq}\0${ref}\0${previousSignature}`. */
  signature: string;
}

/**
 * The settlement backend: verifies signed mandates, enforces replay
 * protection (a nonce is consumed exactly once), and records a final,
 * cryptographically-chained receipt ledger. Runs in-process.
 */
export class SettlementServer {
  readonly key: SettlementKey;
  readonly clock: Clock;
  private readonly consumed = new Set<string>();
  private readonly ledger: LedgerRecord[] = [];

  constructor(options: { key: SettlementKey; clock?: Clock }) {
    this.key = options.key;
    this.clock = options.clock ?? systemClock;
  }

  /** Pure: is this mandate's signature valid and in-window? (No state change.) */
  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) }).valid;
  }

  /** Verify and, on first use, consume the nonce, then mint a receipt. */
  verify(m: PaymentMandate): VerifyResult {
    const v = verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) });
    if (!v.valid) return v;
    if (this.consumed.has(m.nonce)) {
      return { valid: false, reason: 'replayed-proof' };
    }
    return { valid: true };
  }

  /**
   * The payment commit. Verifies, rejects a replayed nonce (throwing
   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   */
  settle(m: PaymentMandate): RailSettlement {
    const v = this.verify(m);
    if (!v.valid) {
      throw new RailError(
        `settlement rejected: ${v.reason ?? 'unknown'}`,
        'RAIL_SETTLE',
        undefined,
        v.reason === 'replayed-proof',
      );
    }
    const settledAt = this.clock.now();
    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
    const receipt: SettlementReceipt = {
      settlementRef,
      origin: m.origin,
      url: m.url,
      amountMicros: m.amountMicros,
      currency: m.currency,
      nonce: m.nonce,
      issuedAt: m.issuedAt,
      settledAt,
    };
    const prevSig = this.ledger.length > 0 ? this.ledger[this.ledger.length - 1]!.signature : 'genesis';
    const seq = this.ledger.length + 1;
    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
    const signature = signBytes(this.key, chain);
    this.ledger.push({ seq, receipt, signedAt: settledAt, signature });
    this.consumed.add(m.nonce);
    return {
      rail: 'self402',
      settlementRef,
      amountMicros: m.amountMicros,
      currency: m.currency,
      settledAt,
    };
  }

  /** The current settlement ledger (a copy) — surfaced on the audit view. */
  ledger(): LedgerRecord[] {
    return this.ledger.map((r) => ({ ...r, receipt: { ...r.receipt } }));
  }

  /** How many distinct nonces have been settled (== ledger length). */
  settledCount(): number {
    return this.ledger.length;
  }
}

/**
 * A `PaymentRail` backed by a settlement backend (in-process
 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
 * — the broker only sees `quote/authorize/settle`.
 */
export class SelfHosted402Rail implements PaymentRail {
  readonly id = 'self402';

  constructor(
    private readonly backend: SettlementBackend,
    private readonly key: SettlementKey,
    private readonly opts: {
      priceMicros: Micros;
      currency?: string;
      clock?: Clock;
      origin?: string;
    },
  ) {}

  async quote(_req: PaymentRequest): Promise<Quote> {
    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
    return {
      unitsMicros: this.opts.priceMicros,
      currency: this.opts.currency ?? 'USD',
      rail: this.id,
      settlement: 'immediate',
      expiresAt: new Date(nowMs + 60_000).toISOString(),
    };
  }

  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
    const mandate = buildMandate({
      origin,
      url: String(req.url),
      amountMicros: quote.unitsMicros,
      currency: this.opts.currency ?? 'USD',
      recipient: this.key.keyId,
      clock: this.opts.clock ?? systemClock,
      key: this.key,
    });
    const xPayment = b64url(Buffer.from(JSON.stringify(mandate), 'utf8'));
    return {
      scheme: this.id,
      payload: JSON.stringify(mandate),
      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
    };
  }

  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
    if (mandate.url !== String(req.url)) {
      throw new RailError('settlement mandate does not match the request', 'RAIL_SETTLE');
    }
    return this.backend.settle(mandate);
  }
}

/**
 * The backend contract the rail commits through: the settle commit, a pure
 * `isValidMandate` cross-check (an origin can use it), and the key id the
 * receipt references.
 */
export interface SettlementBackend {
  settle(mandate: PaymentMandate): RailSettlement;
  isValidMandate(mandate: PaymentMandate): boolean;
  readonly keyId: string;
}

// `SettlementServer` is synchronous at its crypto core, but the rail is async,
// so wrap the commit in a resolved promise to keep one uniform shape.
function ok(s: RailSettlement): Promise<RailSettlement> {
  return Promise.resolve(s);
}

export class InProcessSettlementBackend implements SettlementBackend {
  constructor(private readonly server: SettlementServer) {}
  readonly keyId = this.server.key.keyId;
  settle(mandate: PaymentMandate): Promise<RailSettlement> {
    return ok(this.server.settle(mandate));
  }
  isValidMandate(mandate: PaymentMandate): boolean {
    return this.server.isValidMandate(mandate);
  }
}

/**
 * Convenience: a `SelfHosted402Rail` over an in-process `SettlementServer`,
 * sharing its key. This is the default wiring in `packages/gateway/src/server.ts`.
 */
export function makeSelf402Rail(
  server: SettlementServer,
  options: { priceMicros: Micros; currency?: string; clock?: Clock; origin?: string } = {},
): SelfHosted402Rail {
  return new SelfHosted402Rail(
    new InProcessSettlementBackend(server),
    server.key,
    options,
  );
}

/** The decoded wire payload carried in the `x-payment` header. */
export interface XPayment {
  type: string;
  mandate: PaymentMandate;
}

/** Encode the proof header value (`x-payment`). */
export function encodeXPayment(mandate: PaymentMandate): string {
  return b64url(
    Buffer.from(
      JSON.stringify({ type: PAYMENT_MANDATE_TYPE, mandate } satisfies XPayment),
      'utf8',
    ),
  );
}

/** Decode the proof header value; throws on malformed input. */
export function decodeXPayment(value: string): PaymentMandate {
  let raw: string;
  try {
    raw = Buffer.from(fromB64url(value), 'utf8').toString('utf8');
  } catch (cause) {
    throw new RailError('malformed x-payment header', 'SETTLEMENT_DECODE', cause);
  }
  let parsed: XPayment;
  try {
    parsed = JSON.parse(raw) as XPayment;
  } catch (cause) {
    throw new RailError('x-payment is not JSON', 'SETTLEMENT_DECODE', cause);
  }
  if (!parsed || parsed.type !== PAYMENT_MANDATE_TYPE || !parsed.mandate) {
    throw new RailError('unknown x-payment shape', 'SETTLEMENT_DECODE');
  }
  return parsed.mandate;
}

/**
 * A `SettlementBackend` that commits against a *remote* settlement service over
 * HTTP (standalone `SettlementHttpServer`). Lets the backend run on its own
 * host while the rail stays identical. `isValidMandate` is a local signature
 * check (the remote cannot see the broker's key) plus a freshness read.
 */
export class HttpSettlementClient implements SettlementBackend {
  constructor(
    private readonly url: string,
    private readonly key: SettlementKey,
  ) {}

  get keyId(): string {
    return this.key.keyId;
  }

  isValidMandate(m: PaymentMandate): boolean {
    return verifyMandate(m, this.key, { nowMs: Date.now() }).valid;
  }

  async settle(m: PaymentMandate): Promise<RailSettlement> {
    const res = await fetch(`${this.url.replace(/\/$/, '')}/settle`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(m),
    });
    if (!res.ok) {
      // A settlement rejection (e.g. replayed nonce) is the payment rail
      // "still demanding payment" — surface it as a non-retryable settle fault.
      let reason: string | undefined;
      try {
        reason = (await res.json()).reason;
      } catch {
        /* ignore */
      }
      throw new RailError(
        `settlement service returned ${res.status}${reason ? `: ${reason}` : ''}`,
        'RAIL_SETTLE',
        undefined,
        reason === 'replayed-proof',
      );
    }
    const body = (await res.json()) as RailSettlement & { receipt: SettlementReceipt };
    if (!body.settlementRef) {
      throw new RailError('settlement service returned no ref', 'RAIL_SETTLE');
    }
    return body;
  }
}

